export fn iso7816_d4_padding(v:[*]const i64,n:usize)callconv(.c)i64{if(n<3 or n>27)return -1;const mode=v[0];const block=v[1];const len=v[2];if(mode<0 or mode>2 or (mode==0 and (block<1 or block>8)) or (mode!=0 and block!=0) or len<0 or len>24 or n!=@as(usize,@intCast(len+3)))return -1;var b:[32]i64=undefined;for(0..@intCast(len))|i|{b[i]=v[i+3];if(b[i]<0 or b[i]>255)return -1;}if(mode==0){const out=(len/block+1)*block;if(out>32)return -1;b[@intCast(len)]=128;for(@intCast(len+1)..@intCast(out))|i|{b[i]=0;}return out-len;}if(mode==1){var i:isize=@as(isize,@intCast(len))-1;while(i>=0 and b[@intCast(i)]==0){i-=1;}if(i>=0 and b[@intCast(i)]==128)return @intCast(i);return -1;}var marker:i64=-1;var zero_suffix=true;var j:isize=@as(isize,@intCast(len))-1;while(j>=0):(j-=1){if(zero_suffix and b[@intCast(j)]==128)marker=@intCast(j);if(b[@intCast(j)]!=0)zero_suffix=false;}if(marker>=0)return len-marker;return -1;}
